        let settled_before = match gate_read {
            Some(read) => Some(read.bytes),
            None => Some(self.establish_entry_authority(
                &guard,
                &dir_fd,
                &marker_fd,
                marker_id,
                target_name.as_os_str(),
                &target_c,
                &record_c,
            )?),
        };
        self.checkpoint_seq = self.checkpoint_seq.saturating_add(1);
