        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
