    #[test]
    fn new111_legacy_verified_namespace_conflict_refuses() {
        // P2fix18 NEW-111 (Tier-1 adjacent edge — the
        // namespace-conflict arm): a legacy-verified open
        // whose new namespace gains a record out-of-band
        // refuses the first write before the entry decision
        // (a new-namespace record over verified legacy
        // authority is a conflict — never entered around).
        // Everything survives untouched.
        let base = unique_dir("legacy-ns-conflict");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut prior =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("prior opens");
        prior.build_service().expect("prior commits");
        drop(prior);
        let target_before = std::fs::read(&ckpt).unwrap();
        let legacy_bytes = std::fs::read(record_path_for(&ckpt)).unwrap();
        let _ = std::fs::remove_dir_all(p.join(super::SETTLED_DIR_NAME));
        let legacy_path = p.join("ckpt.json.settled");
        std::fs::write(&legacy_path, &legacy_bytes).unwrap();
        let mut presenter = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("the legacy authority governs at reopen");
        // A new-namespace record appears out-of-band over
        // the verified legacy authority.
        let conflict = super::SettledRecord {
            target_sha256: "5".repeat(64),
            checkpoint_seq: 555,
        };
        let conflict_bytes = super::render_settlement_record(&conflict);
        std::fs::create_dir_all(p.join(super::SETTLED_DIR_NAME)).unwrap();
        std::fs::write(record_path_for(&ckpt), &conflict_bytes).unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let err = presenter
            .flush_checkpoint()
            .expect_err("a namespace conflict refuses before entry");
        assert!(
            format!("{err:?}").contains("appeared over verified legacy authority"),
            "the refusal names the conflict: {err:?}"
        );
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            target_before,
            "the target survives untouched"
        );
        assert_eq!(
            std::fs::read(&legacy_path).unwrap(),
            legacy_bytes,
            "the verified legacy record survives untouched"
        );
        assert_eq!(
            std::fs::read(record_path_for(&ckpt)).unwrap(),
            conflict_bytes,
            "the conflicting record survives (never adopted)"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new111_live_gate_conflicting_record_refuses() {
        // P2fix18 NEW-111 (authority bound to the verified
        // transaction): a valid-but-conflicting reread record
        // refuses BEFORE data publish — the write never
        // adopts out-of-band authority as its baseline. The
        // target, the conflicting marker, and the recoverable
        // prior all survive; zero staging runs. Pre-fix: the
        // write adopts the stranger and commits (RED).
        let base = unique_dir("live-gate-conflict");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        presenter.flush_checkpoint().expect("first commit settles");
        let target_before = std::fs::read(&ckpt).unwrap();
        let record_before = std::fs::read(record_path_for(&ckpt)).unwrap();
        // A second window lands (the write has data to
        // publish); the standing record is swapped
        // out-of-band for a VALID but conflicting one.
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let conflict = super::SettledRecord {
            target_sha256: "9".repeat(64),
            checkpoint_seq: 999,
        };
        let conflict_bytes = super::render_settlement_record(&conflict);
        assert!(
            super::parse_settlement_record(&conflict_bytes).is_ok(),
            "premise: the conflicting record is strictly valid"
        );
        std::fs::write(record_path_for(&ckpt), &conflict_bytes).unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let err = presenter
            .flush_checkpoint()
            .expect_err("a valid-but-conflicting record refuses before publish");
        assert!(
            format!("{err:?}").contains("changed since verification"),
            "the refusal names the authority change: {err:?}"
        );
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            target_before,
            "the target survives untouched"
        );
        assert_eq!(
            std::fs::read(record_path_for(&ckpt)).unwrap(),
            conflict_bytes,
            "the conflicting marker survives (never clobbered)"
        );
        assert!(
            staging_residue(&p).is_empty(),
            "zero staging runs before the refusal: {:?}",
            staging_residue(&p)
        );
        // Restoring the verified record lets the SAME
        // instance commit whole (nothing was adopted).
        std::fs::write(record_path_for(&ckpt), &record_before).unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        presenter
            .flush_checkpoint()
            .expect("the same instance commits after restore");
        assert_eq!(
            presenter.folded_tip(),
            (Some(0), Some(1)),
            "the restored write advances the tip"
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the committed tree");
        assert_eq!(q.folded_tip(), (Some(0), Some(1)), "the new tip stands");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new111_legacy_entry_conflicting_record_refuses() {
        // P2fix18 NEW-111 (no legacy fall-through past a
        // valid conflict): a markerless open adopts the
        // target; a valid legacy record confirming a
        // DIFFERENT transaction then refuses the first write
        // (never fresh-entry around asserted authority).
        // The target, the legacy record, and the absent
        // new-namespace slot all survive. Pre-fix: the
        // first write entries around it and commits (RED).
        let base = unique_dir("legacy-entry-conflict");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        // A committed tree, then stripped to a pure
        // markerless adoption (no records anywhere).
        let mut prior =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("prior opens");
        prior.build_service_staged().expect("staged fold advances");
        prior.flush_checkpoint().expect("prior commits");
        drop(prior);
        let target_before = std::fs::read(&ckpt).unwrap();
        let _ = std::fs::remove_dir_all(p.join(super::SETTLED_DIR_NAME));
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("markerless opens");
        // A valid legacy record confirming a DIFFERENT
        // transaction appears before the first write.
        let conflict = super::SettledRecord {
            target_sha256: "7".repeat(64),
            checkpoint_seq: 777,
        };
        let conflict_bytes = super::render_settlement_record(&conflict);
        assert!(
            super::parse_settlement_record(&conflict_bytes).is_ok(),
            "premise: the conflicting legacy record is strictly valid"
        );
        let legacy_path = p.join("ckpt.json.settled");
        std::fs::write(&legacy_path, &conflict_bytes).unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let err = presenter
            .flush_checkpoint()
            .expect_err("a valid-but-conflicting legacy record refuses entry");
        assert!(
            format!("{err:?}").contains("confirms a different transaction"),
            "the refusal names the conflict: {err:?}"
        );
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            target_before,
            "the target survives untouched"
        );
        assert_eq!(
            std::fs::read(&legacy_path).unwrap(),
            conflict_bytes,
            "the conflicting legacy record survives untouched"
        );
        assert!(
            !record_path_for(&ckpt).exists(),
            "no entry commits (the record slot stays absent)"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new112_regular_file_parent_refuses_not_fresh() {
        // P2fix18 NEW-112 (Tier-1 adjacent edge — the
        // non-directory parent that is not a FIFO): a
        // regular file at the checkpoint-parent path
        // refuses loudly (never a silent fresh start —
        // only a genuinely missing path defers).
        let base = unique_dir("regular-parent");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::write(&p, b"not-a-directory").unwrap();
        let ckpt = p.join("ckpt.json");
        let err = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect_err("a regular-file parent refuses the open");
        assert!(
            format!("{err:?}").contains("not an openable directory"),
            "the refusal names the non-directory parent: {err:?}"
        );
        // Removing it defers fresh (the NEW-18 rule for
        // genuinely missing paths still holds).
        std::fs::remove_file(&p).unwrap();
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("a missing parent still defers fresh");
        assert!(
            q.checkpoint_parent_id.is_none(),
            "the deferred open stays unbound"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new112_parent_fifo_refuses_promptly() {
        // P2fix18 NEW-112 (nonblocking verified parent open):
        // a FIFO at the checkpoint-parent path refuses
        // PROMPTLY at open and at write (the open never
        // blocks, so a planted FIFO cannot wedge the reader
        // before the bounded intake runs). Pre-fix: both
        // opens block forever (RED — the bounded open
        // times out).
        let base = unique_dir("parent-fifo");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        // OPEN leg: the parent path is a FIFO — the open
        // returns within the bound with a refusal (never a
        // wedged reader, never a silent fresh start).
        std::fs::remove_dir(&p).unwrap();
        mkfifo_at(&p);
        let err = open_bounded(&out, &ckpt, 10).expect("a FIFO parent refuses the open");
        assert!(
            err.contains("not an openable directory"),
            "the refusal names the non-directory parent: {err}"
        );
        std::fs::remove_file(&p).unwrap();
        // WRITE leg: a valid bound presenter whose parent is
        // swapped for a FIFO refuses the flush promptly.
        std::fs::create_dir_all(&p).unwrap();
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        presenter.flush_checkpoint().expect("first commit settles");
        std::fs::rename(&p, base.join("p.saved")).unwrap();
        mkfifo_at(&p);
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let _ = tx.send(format!("{:?}", presenter.flush_checkpoint()));
        });
        let text = rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("the flush returns within the bound (no wedged parent open)");
        assert!(
            text.contains("not an openable directory"),
            "the flush refusal names the non-directory parent: {text}"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new112_rebind_before_open_binds_opened_parent() {
        // P2fix18 NEW-112 (handle-derived stored identity): a
        // parent rebind BEFORE the open binds the OPENED
        // handle — the reopen adopts the directory it
        // actually read, and the stored binding is that
        // handle's identity (a later write binds the same
        // directory — no pathname-sample split can strand
        // it as "replaced"). Pre-fix: the write refuses on
        // the stale construction-time sample (RED).
        let base = unique_dir("pre-open-rebind");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        // The decoy commits window 0 only (totals 10).
        let d = base.join("d");
        std::fs::create_dir_all(&d).unwrap();
        let decoy_ckpt = d.join("ckpt.json");
        let mut decoy =
            Presenter::open_with_checkpoint(&out, &decoy_ckpt, 1, "export").expect("decoy opens");
        decoy.build_service_staged().expect("decoy folds");
        decoy.flush_checkpoint().expect("decoy commits");
        drop(decoy);
        let decoy_id = dir_id(&d);
        // The original commits windows 0+1 (totals 20).
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut orig =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("original opens");
        orig.build_service_staged().expect("original folds");
        orig.flush_checkpoint().expect("original commits");
        drop(orig);
        // Rebind BEFORE the open: the path now names the
        // decoy directory.
        let (p2, d2) = (p.clone(), d.clone());
        let ran = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let ran2 = ran.clone();
        super::pre_parent_open_hook::arm(move || {
            std::fs::rename(&p2, p2.with_extension("orig")).unwrap();
            std::fs::rename(&d2, &p2).unwrap();
            ran2.store(true, std::sync::atomic::Ordering::Relaxed);
        });
        let mut q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("the reopen binds the opened parent");
        super::pre_parent_open_hook::disarm();
        assert!(
            ran.load(std::sync::atomic::Ordering::Relaxed),
            "the rebind hook ran before the open"
        );
        assert_eq!(q.folded_tip(), (Some(0), Some(0)), "the decoy tip stands");
        assert_eq!(
            q.fold_totals(),
            (10, [10, 0, 0, 0]),
            "the reopen adopts the directory it actually read"
        );
        assert_eq!(
            q.checkpoint_parent_id,
            Some(decoy_id),
            "the stored binding derives from the opened handle"
        );
        // The write binds the SAME directory (no stale
        // pathname sample can strand it as replaced).
        q.build_service_staged().expect("staged fold advances");
        q.flush_checkpoint()
            .expect("the write binds the opened parent");
        assert_eq!(q.folded_tip(), (Some(0), Some(1)), "the tip advances");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new108_decision_source_substitution_refuses_preserved() {
        // P2fix18 NEW-108 (decision binds the staged
        // inode/bytes): a rebound decision SOURCE (or a
        // same-inode stage rewrite after staging) refuses
        // BEFORE the rename — the decision never moves
        // foreign bytes onto the record slot, and the old
        // authority is never touched (zero renames). The
        // retry re-stages and commits; the foreign object
        // and our staged bytes both survive. Pre-fix: the
        // rename moves the substitute and only the
        // post-decision readback catches it (RED —
        // marker_probe proves the decision ran).
        for shape in ["rebind", "rewrite"] {
            let base = unique_dir(&format!("decision-source-{shape}"));
            let out = base.join("out");
            std::fs::create_dir_all(&out).unwrap();
            let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
            std::fs::write(
                out.join("window-0000000000.json"),
                serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
            )
            .unwrap();
            let p = base.join("p");
            std::fs::create_dir_all(&p).unwrap();
            let ckpt = p.join("ckpt.json");
            let mut presenter =
                Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
            presenter.build_service().expect("first fold commits");
            let record_before = std::fs::read(record_path_for(&ckpt)).unwrap();
            let record_id_before = dir_id(&record_path_for(&ckpt));
            std::fs::write(
                out.join("window-0000000001.json"),
                serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
            )
            .unwrap();
            presenter
                .build_service_staged()
                .expect("staged fold advances");
            super::marker_probe::take();
            // Substitute the SOURCE after staging (the
            // destination stays pristine — only the source
            // binding can refuse this).
            let marker_dir = p.join(super::SETTLED_DIR_NAME);
            let (md2, shape2) = (marker_dir.clone(), shape.to_string());
            let stage_name = std::sync::Arc::new(std::sync::Mutex::new(String::new()));
            let stage_name2 = stage_name.clone();
            let ours_copy = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
            let ours_copy2 = ours_copy.clone();
            super::pre_decision_rename_hook::arm(move || {
                let stages: Vec<_> = std::fs::read_dir(&md2)
                    .unwrap()
                    .flatten()
                    .map(|e| e.file_name().to_string_lossy().into_owned())
                    .filter(|n| n.contains(".staging-"))
                    .collect();
                assert_eq!(stages.len(), 1, "premise: one staged source");
                *stage_name2.lock().unwrap() = stages[0].clone();
                let stage = md2.join(&stages[0]);
                *ours_copy2.lock().unwrap() = std::fs::read(&stage).unwrap();
                if shape2 == "rebind" {
                    std::fs::rename(&stage, md2.join("ckpt.json.staging-ours-away")).unwrap();
                    std::fs::write(&stage, b"foreign-stage-substitute").unwrap();
                } else {
                    let len = std::fs::read(&stage).unwrap().len();
                    std::fs::write(&stage, vec![b'R'; len]).unwrap();
                }
            });
            let err = presenter
                .flush_checkpoint()
                .expect_err("a substituted decision source refuses");
            super::pre_decision_rename_hook::disarm();
            assert!(
                format!("{err:?}").contains("settlement stage source changed"),
                "{shape}: the refusal names the source: {err:?}"
            );
            assert_eq!(
                super::marker_probe::take(),
                0,
                "{shape}: the decision rename never ran"
            );
            assert_eq!(
                std::fs::read(record_path_for(&ckpt)).unwrap(),
                record_before,
                "{shape}: the old authority bytes stand untouched"
            );
            assert_eq!(
                dir_id(&record_path_for(&ckpt)),
                record_id_before,
                "{shape}: the old authority object stands untouched"
            );
            let stage_name = stage_name.lock().unwrap().clone();
            if shape == "rebind" {
                assert_eq!(
                    std::fs::read(marker_dir.join(&stage_name)).unwrap(),
                    b"foreign-stage-substitute",
                    "the foreign source survives (never moved)"
                );
                assert_eq!(
                    std::fs::read(marker_dir.join("ckpt.json.staging-ours-away")).unwrap(),
                    *ours_copy.lock().unwrap(),
                    "our staged bytes survive aside (never moved)"
                );
            } else {
                // P2fix19 NEW-115: the rewrite leg asserts
                // byte survival too (the withdrawal is
                // byte-conditional — the rewritten bytes
                // survive, never unlinked).
                let ours_len = ours_copy.lock().unwrap().len();
                assert_eq!(
                    std::fs::read(marker_dir.join(&stage_name)).unwrap(),
                    vec![b'R'; ours_len],
                    "the rewritten bytes survive (never unlinked)"
                );
            }
            // The retry re-stages and commits whole.
            presenter
                .build_service_staged()
                .expect("staged fold advances");
            let outcome = presenter.flush_checkpoint().expect("the retry commits");
            assert!(
                !outcome.residue.is_empty(),
                "{shape}: the leftover declares: {:?}",
                outcome.residue
            );
            drop(presenter);
            let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
                .expect("reopen on the committed tree");
            assert_eq!(
                q.folded_tip(),
                (Some(0), Some(1)),
                "{shape}: the new tip stands"
            );
            let _ = std::fs::remove_dir_all(&base);
        }
    }

    #[test]
    fn new108_legacy_sweep_same_inode_rewrite_refuses() {
        // P2fix18 NEW-108 (byte-conditional legacy sweep): a
        // same-inode rewrite of the legacy record between
        // the byte-verified read and the removal refuses
        // the sweep — the rewritten bytes survive, never
        // unlinked; the migration itself stands and the
        // leftover declares as residue. Pre-fix: the
        // rewritten bytes are unlinked (RED).
        let base = unique_dir("legacy-sweep-rewrite");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        // A settled-legacy tree: the target carries the
        // prior, the beside-target record confirms it, no
        // new-namespace record stands.
        let mut prior =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("prior opens");
        prior.build_service().expect("prior commits");
        drop(prior);
        let legacy_bytes = std::fs::read(record_path_for(&ckpt)).unwrap();
        let _ = std::fs::remove_dir_all(p.join(super::SETTLED_DIR_NAME));
        let legacy_path = p.join("ckpt.json.settled");
        std::fs::write(&legacy_path, &legacy_bytes).unwrap();
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("reopen adopts");
        assert!(
            !presenter.recovered_unsettled_prior(),
            "premise: direct adoption (no recovery)"
        );
        // The first write migrates; the sweep's removal
        // finds same-inode rewritten bytes.
        let rewritten = vec![b'R'; legacy_bytes.len()];
        let (legacy2, rewritten2) = (legacy_path.clone(), rewritten.clone());
        super::pre_legacy_sweep_hook::arm(move || {
            use std::io::Write as _;
            let mut f = std::fs::OpenOptions::new()
                .write(true)
                .open(&legacy2)
                .unwrap();
            f.write_all(&rewritten2).unwrap();
            f.flush().unwrap();
        });
        super::marker_probe::take();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let outcome = presenter.flush_checkpoint().expect("the migration commits");
        super::pre_legacy_sweep_hook::disarm();
        assert_eq!(
            super::marker_probe::take(),
            2,
            "the entry commit + the per-write decision both ran"
        );
        assert!(
            outcome.residue.join(" ").contains("changed during removal"),
            "the leftover declares: {:?}",
            outcome.residue
        );
        assert_eq!(
            std::fs::read(&legacy_path).unwrap(),
            rewritten,
            "the rewritten bytes survive (never unlinked)"
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the migrated tree");
        assert_eq!(q.folded_tip(), (Some(0), Some(0)), "the tip stands");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new108_rollback_sync_binding_loss_refuses() {
        // P2fix18 NEW-108 (rollback rechecks the marker
        // binding after sync, before removal): a marker
        // namespace lost during the authority-restore sync
        // fails the rollback — the removal never runs under
        // the false authority assumption, the decided
        // payload stands for restart recovery, and the
        // outcome never claims a restore that no longer
        // stands. Pre-fix: the removal proceeds and the
        // rollback claims success (RED).
        let base = unique_dir("rollback-binding-loss");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter.build_service().expect("first fold commits");
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        drop(presenter);
        // A dead owner (the parent's pid is alive while the
        // child runs — forge it dead, per the new100 pins).
        let (_forged, _forged_seq) = forge_dead_owner(&ckpt);
        // The forged bytes are the true prior (the child
        // adopts them; the swapback restores them).
        let target_before = std::fs::read(&ckpt).unwrap();
        // The child re-opens, folds the staged window, and
        // runs the faulted flush: its post-decision marker
        // sync fails (rollback with restore) and the marker
        // namespace moves aside during the restore sync —
        // the child aborts (never a misaligned return) with
        // the binding loss named on stderr. Pre-fix: the
        // rollback claims success and the child returns
        // (RED — no abort).
        let stderr = run_abort_child(&base, &out, &ckpt, "abort-rollback-binding-loss");
        assert!(
            stderr.contains("marker binding"),
            "the abort names the binding loss: {stderr:?}"
        );
        // The decided payload stands (never removed under
        // the lost binding) and the target is whole.
        let stages = staging_residue(&p);
        assert_eq!(stages.len(), 1, "the decided stage stands: {stages:?}");
        let stage_body: serde_json::Value =
            serde_json::from_slice(&std::fs::read(p.join(&stages[0])).unwrap()).unwrap();
        assert_eq!(
            stage_body["watermark_seq"],
            serde_json::json!(1),
            "the standing stage carries the decided payload"
        );
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            target_before,
            "the target carries the restored prior"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new108_unlink_final_window_displaces_loudly() {
        // P2fix18 NEW-108 (conditional owned removal): a
        // rebind inside the FINAL check→mutation window
        // displaces loudly with every byte surviving — the
        // foreign entry is never removed (single-link: the
        // old code detected-but-destroyed; multi-link: the
        // old post-confirm even passed silently — RED).
        for (tag, multilink) in [("single", false), ("multi", true)] {
            let base = unique_dir(&format!("unlink-window-{tag}"));
            let d = base.join("d");
            std::fs::create_dir_all(&d).unwrap();
            let victim = d.join("victim");
            let ours = b"our-owned-bytes".to_vec();
            std::fs::write(&victim, &ours).unwrap();
            if multilink {
                std::fs::hard_link(&victim, d.join("victim2")).unwrap();
            }
            let dir_fd = std::fs::File::open(&d).unwrap();
            let ours_id = super::file_id(&std::fs::File::open(&victim).unwrap()).unwrap();
            let name = std::ffi::CString::new("victim").unwrap();
            let (d2, victim2) = (d.clone(), victim.clone());
            super::unlink_final_hook::arm(move || {
                std::fs::rename(&victim2, d2.join("away")).unwrap();
                std::fs::write(&victim2, b"foreign-window-bytes").unwrap();
            });
            let out = super::unlink_owned(&dir_fd, &name, ours_id);
            super::unlink_final_hook::disarm();
            assert!(
                matches!(out, Ok(false)),
                "{tag}: interference refuses without removal: {out:?}"
            );
            assert_eq!(
                std::fs::read(&victim).unwrap(),
                b"foreign-window-bytes",
                "{tag}: the foreign entry survives at its name"
            );
            assert_eq!(
                std::fs::read(d.join("away")).unwrap(),
                ours,
                "{tag}: our entry survives aside"
            );
            if multilink {
                assert_eq!(
                    std::fs::read(d.join("victim2")).unwrap(),
                    ours,
                    "{tag}: our second link survives"
                );
            }
            // No trash lingers (the displacement restored
            // the name — nothing to declare).
            assert!(
                std::fs::read_dir(&d)
                    .unwrap()
                    .flatten()
                    .all(|e| !e.file_name().to_string_lossy().contains(".staging-trash-")),
                "{tag}: no trash lingers"
            );
            let _ = std::fs::remove_dir_all(&base);
        }
    }

    #[test]
    fn new115_trash_substitution_detected_loudly() {
        // P2fix19 NEW-115 (conditional trash unlink): a
        // substitute planted at the TRASH name AFTER it
        // verifies as ours is NEVER silently removed —
        // the pinned link-count check reports it loudly
        // (identity AND bytes variants share the core, so
        // both legs run). Shape `rename-plant`: ours moves
        // aside, foreign planted — pre-fix `Ok(true)`
        // with the foreign bytes destroyed (RED). Shape
        // `unlink-plant`: ours unlinked, foreign planted
        // — pre-fix `Ok(true)` (RED); post-fix the
        // pre-unlink recheck refuses BEFORE the unlink, so
        // the foreign bytes survive too.
        for shape in ["rename-plant", "unlink-plant"] {
            for bound in ["identity", "bytes"] {
                let base = unique_dir(&format!("trash-subst-{shape}-{bound}"));
                let d = base.join("d");
                std::fs::create_dir_all(&d).unwrap();
                let victim = d.join("victim");
                let ours = b"our-owned-bytes-115".to_vec();
                std::fs::write(&victim, &ours).unwrap();
                let dir_fd = std::fs::File::open(&d).unwrap();
                let ours_id = super::file_id(&std::fs::File::open(&victim).unwrap()).unwrap();
                let name = std::ffi::CString::new("victim").unwrap();
                let (d2, ours2, shape2) = (d.clone(), ours.clone(), shape.to_string());
                super::unlink_trash_hook::arm(move || {
                    let trash: std::path::PathBuf = std::fs::read_dir(&d2)
                        .unwrap()
                        .flatten()
                        .map(|e| e.file_name().to_string_lossy().into_owned())
                        .filter(|n| n.contains(".staging-trash-"))
                        .map(|n| d2.join(n))
                        .next()
                        .expect("premise: our trash stands displaced");
                    assert_eq!(
                        std::fs::read(&trash).unwrap(),
                        ours2,
                        "premise: the trash carries our bytes"
                    );
                    if shape2 == "rename-plant" {
                        std::fs::rename(&trash, d2.join("ours-away")).unwrap();
                    } else {
                        std::fs::remove_file(&trash).unwrap();
                    }
                    std::fs::write(&trash, b"foreign-trash-bytes").unwrap();
                });
                let out = if bound == "bytes" {
                    super::unlink_owned_bytes(&dir_fd, &name, ours_id, &ours)
                } else {
                    super::unlink_owned(&dir_fd, &name, ours_id)
                };
                super::unlink_trash_hook::disarm();
                let err = out.expect_err(&format!(
                    "{shape}/{bound}: a trash substitution never succeeds silently"
                ));
                assert!(
                    format!("{err:?}").contains("trash"),
                    "{shape}/{bound}: the report names the trash substitution: {err:?}"
                );
                if shape == "rename-plant" {
                    // The raced syscall already unlinked the
                    // foreign bytes — LOUDLY reported, never
                    // silent; our displaced bytes survive
                    // aside byte-identical.
                    assert_eq!(
                        std::fs::read(d.join("ours-away")).unwrap(),
                        ours,
                        "{bound}: our displaced bytes survive aside"
                    );
                    assert!(
                        std::fs::read_dir(&d).unwrap().flatten().all(|e| {
                            !e.file_name().to_string_lossy().contains(".staging-trash-")
                        }),
                        "{bound}: no trash lingers"
                    );
                } else {
                    // The pre-unlink recheck refused BEFORE
                    // the unlink — the foreign entry
                    // survives at the trash name.
                    let trash: Vec<_> = std::fs::read_dir(&d)
                        .unwrap()
                        .flatten()
                        .map(|e| e.file_name().to_string_lossy().into_owned())
                        .filter(|n| n.contains(".staging-trash-"))
                        .collect();
                    assert_eq!(trash.len(), 1, "{bound}: one trash stands");
                    assert_eq!(
                        std::fs::read(d.join(&trash[0])).unwrap(),
                        b"foreign-trash-bytes",
                        "{bound}: the foreign bytes survive (never unlinked)"
                    );
                }
                let _ = std::fs::remove_dir_all(&base);
            }
        }
    }

    #[test]
    fn new115_displacement_survives_parent_reparent() {
        // P2fix19 NEW-115 (reparenting during displacement):
        // the parent directory moves aside (and a fresh
        // directory with a same-name decoy appears at its
        // path) INSIDE the trash-verify→unlink interval —
        // the fd-relative + pinned-identity removal still
        // removes exactly OUR object (link-count verified),
        // the decoy stands untouched, and no trash lingers.
        // (Control pin — GREEN both sides: fd-relative ops
        // are reparent-immune by construction; the pin
        // locks the boundary against regressions.)
        let base = unique_dir("trash-reparent");
        let d = base.join("d");
        std::fs::create_dir_all(&d).unwrap();
        let victim = d.join("victim");
        let ours = b"our-owned-bytes-115".to_vec();
        std::fs::write(&victim, &ours).unwrap();
        let dir_fd = std::fs::File::open(&d).unwrap();
        let ours_id = super::file_id(&std::fs::File::open(&victim).unwrap()).unwrap();
        let name = std::ffi::CString::new("victim").unwrap();
        let (base2, d2) = (base.clone(), d.clone());
        super::unlink_trash_hook::arm(move || {
            std::fs::rename(&d2, base2.join("d-aside")).unwrap();
            std::fs::create_dir_all(&d2).unwrap();
            std::fs::write(d2.join("victim"), b"decoy-bytes").unwrap();
        });
        let out = super::unlink_owned(&dir_fd, &name, ours_id);
        super::unlink_trash_hook::disarm();
        assert!(
            matches!(out, Ok(true)),
            "the fd-relative removal still removes exactly ours: {out:?}"
        );
        assert_eq!(
            std::fs::read(d.join("victim")).unwrap(),
            b"decoy-bytes",
            "the rebound-path decoy stands untouched"
        );
        assert!(
            std::fs::read_dir(base.join("d-aside"))
                .unwrap()
                .flatten()
                .all(|e| !e.file_name().to_string_lossy().contains(".staging-trash-")),
            "no trash lingers in the reparented directory"
        );
        assert!(
            !base.join("d-aside").join("victim").exists(),
            "our entry is gone from the reparented directory"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new115_same_inode_decision_rewrite_preserved() {
        // P2fix19 NEW-115 (byte-conditional decision
        // withdrawal): a same-inode rewrite of the marker
        // stage refuses at the source binding AND the
        // rewritten bytes SURVIVE (never unlinked by the
        // withdrawal) — pre-fix the identity-only
        // withdrawal destroys them (RED). The old
        // authority stands untouched, and the retry
        // re-stages and commits whole.
        let base = unique_dir("decision-rewrite-115");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter.build_service().expect("first fold commits");
        let record_before = std::fs::read(record_path_for(&ckpt)).unwrap();
        let record_id_before = dir_id(&record_path_for(&ckpt));
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        super::marker_probe::take();
        let marker_dir = p.join(super::SETTLED_DIR_NAME);
        let md2 = marker_dir.clone();
        let stage_len = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let stage_len2 = stage_len.clone();
        super::pre_decision_rename_hook::arm(move || {
            let stages: Vec<_> = std::fs::read_dir(&md2)
                .unwrap()
                .flatten()
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .filter(|n| n.contains(".staging-"))
                .collect();
            assert_eq!(stages.len(), 1, "premise: one staged source");
            let stage = md2.join(&stages[0]);
            let len = std::fs::read(&stage).unwrap().len();
            stage_len2.store(len, std::sync::atomic::Ordering::Relaxed);
            std::fs::write(&stage, vec![b'R'; len]).unwrap();
        });
        let err = presenter
            .flush_checkpoint()
            .expect_err("a rewritten decision source refuses");
        super::pre_decision_rename_hook::disarm();
        assert!(
            format!("{err:?}").contains("settlement stage source changed"),
            "the refusal names the source: {err:?}"
        );
        assert_eq!(
            super::marker_probe::take(),
            0,
            "the decision rename never ran"
        );
        assert_eq!(
            std::fs::read(record_path_for(&ckpt)).unwrap(),
            record_before,
            "the old authority bytes stand untouched"
        );
        assert_eq!(
            dir_id(&record_path_for(&ckpt)),
            record_id_before,
            "the old authority object stands untouched"
        );
        // The rewritten bytes SURVIVE at the stage name
        // (byte-conditional withdrawal — never unlinked).
        let len = stage_len.load(std::sync::atomic::Ordering::Relaxed);
        let stages: Vec<_> = std::fs::read_dir(&marker_dir)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.contains(".staging-"))
            .collect();
        assert_eq!(stages.len(), 1, "one rewritten stage stands: {stages:?}");
        assert_eq!(
            std::fs::read(marker_dir.join(&stages[0])).unwrap(),
            vec![b'R'; len],
            "the rewritten bytes survive (never unlinked)"
        );
        // The retry re-stages and commits whole.
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let outcome = presenter.flush_checkpoint().expect("the retry commits");
        assert!(
            !outcome.residue.is_empty(),
            "the leftover declares: {:?}",
            outcome.residue
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the committed tree");
        assert_eq!(q.folded_tip(), (Some(0), Some(1)), "the new tip stands");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new115_same_inode_restore_rewrite_preserved() {
        // P2fix19 NEW-115 (byte-conditional restore
        // withdrawal): a same-inode rewrite of the
        // RESTORE stage inside post-decision rollback
        // refuses the restore AND the rewritten bytes
        // SURVIVE (never unlinked by the withdrawal) —
        // pre-fix the identity-only withdrawal destroys
        // them (RED). The rollback fails and the child
        // aborts (never a misaligned return); the target
        // carries the swapped-back prior and reopen
        // converges onto the decided transaction.
        let base = unique_dir("restore-rewrite-115");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        for seq in 0..2u64 {
            std::fs::write(
                out.join(format!("window-{seq:010}.json")),
                serde_json::to_string(&super::test_envelope(seq, 0, run.clone(), 10)).unwrap(),
            )
            .unwrap();
        }
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter.build_service().expect("first fold commits");
        drop(presenter);
        let (forged_bytes, _forged_seq) = forge_dead_owner(&ckpt);
        std::fs::write(
            out.join("window-0000000002.json"),
            serde_json::to_string(&super::test_envelope(2, 0, run, 10)).unwrap(),
        )
        .unwrap();
        run_abort_child(&base, &out, &ckpt, "abort-restore-stage-rewrite");
        // The rewritten restore stage SURVIVES (never
        // unlinked by the withdrawal).
        let marker_dir = p.join(super::SETTLED_DIR_NAME);
        let restores: Vec<_> = std::fs::read_dir(&marker_dir)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.contains(".staging-restore-"))
            .collect();
        assert_eq!(restores.len(), 1, "one restore stage stands: {restores:?}");
        let rewritten = std::fs::read(marker_dir.join(&restores[0])).unwrap();
        assert!(
            !rewritten.is_empty() && rewritten.iter().all(|b| *b == b'W'),
            "the rewritten restore bytes survive byte-identical"
        );
        // The data publish already swapped back; the
        // record still carries our decided bytes (the
        // restore never replaced them).
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            forged_bytes,
            "the target carries the swapped-back prior"
        );
        // Reopen converges onto the decided transaction
        // via the standing stage (recovery, flagged).
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen converges onto the decided transaction");
        assert!(
            q.recovered_unsettled_prior(),
            "the reopen reports the marker-bound recovery"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    /// Stash a confirmed-displacement pending state
    /// (P2fix19 NEW-116 — shared setup): a first write
    /// fails into an undisplaced stash (the new109
    /// choreography), then the recovery's own unlink
    /// displaces but its trash unlink faults — the
    /// presenter keeps a DISPLACED pending state (the
    /// target stands absent, our object stands at the
    /// trash name). Returns the tree paths + presenter.
    fn new116_stash_displaced(
        tag: &str,
    ) -> (
        std::path::PathBuf,
        std::path::PathBuf,
        std::path::PathBuf,
        Presenter,
    ) {
        let base = unique_dir(tag);
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        let p2 = p.clone();
        super::post_exchange_hook::arm(move || {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(&p2, std::fs::Permissions::from_mode(0o555)).unwrap();
        });
        super::dir_sync_fault::arm(1);
        presenter
            .flush_checkpoint()
            .expect_err("the failed first-write removal fails the flush");
        super::post_exchange_hook::disarm();
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o755)).unwrap();
        assert!(
            presenter.pending_recovery.is_some(),
            "premise: pending stashed"
        );
        // The recovery's own unlink displaces but its
        // trash unlink faults — the displacement
        // confirms, the removal does not.
        super::trash_unlink_fault::arm(1);
        presenter
            .flush_checkpoint()
            .expect_err("the faulted recovery fails");
        super::trash_unlink_fault::reset();
        let pending = presenter
            .pending_recovery
            .as_ref()
            .expect("premise: displaced pending kept");
        assert!(
            pending.displaced_trash.is_some(),
            "premise: the stash carries the confirmed trash"
        );
        assert!(!ckpt.is_file(), "premise: the target stands absent");
        (base, out, ckpt, presenter)
    }

    #[test]
    fn new116_displaced_trash_unlink_resumes() {
        // P2fix19 NEW-116 (partial displacement recovery):
        // a confirmed displacement + failed trash unlink
        // RESUMES (never refuses indefinitely) — the same
        // collector commits + reopens exactly after fault
        // clearance. Pre-fix: the retry re-checks the
        // original target name, finds it absent, and
        // refuses forever (RED).
        let (base, out, ckpt, mut presenter) = new116_stash_displaced("displaced-resume");
        // The fault clears: the SAME instance resumes
        // from the displaced trash and commits whole.
        presenter
            .flush_checkpoint()
            .expect("the retry resumes and commits");
        assert!(
            presenter.pending_recovery.is_none(),
            "the completed resume clears pending"
        );
        assert!(ckpt.is_file(), "the target stands committed");
        assert!(
            std::fs::read_dir(ckpt.parent().unwrap())
                .unwrap()
                .flatten()
                .all(|e| !e.file_name().to_string_lossy().contains(".staging-trash-")),
            "no trash lingers after the resume"
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the recovered commit");
        assert_eq!(q.folded_tip(), (Some(0), Some(0)), "the tip stands");
        assert_eq!(q.fold_totals(), (10, [10, 0, 0, 0]), "the totals stand");
        assert!(
            !q.recovered_unsettled_prior(),
            "a settled commit reopens directly (no recovery)"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new116_remediate_displaced_trash_unlink_resumes() {
        // P2fix19 NEW-116 (remediate-side displacement): the
        // pre-decision rollback's own target-step unlink
        // displaces but its trash unlink faults — the
        // stash carries the confirmed trash (not the
        // original name), and the same collector resumes
        // + commits + reopens exactly after fault
        // clearance. Pre-fix: the retry re-checks the
        // original target name and refuses forever (RED).
        let base = unique_dir("displaced-remediate");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter.build_service().expect("first fold commits");
        // The target vanishes out-of-band (the repair
        // shape — NOREPLACE re-creates it, so the
        // rollback's target step runs the Absent arm with
        // no entry commit in the way).
        std::fs::remove_file(&ckpt).unwrap();
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        // A substitute at the record name fails the
        // record commit BEFORE its decision (the data
        // publish already ran NOREPLACE — the rollback's
        // target step must remove our entry).
        let record = record_path_for(&ckpt);
        let (record2, p2) = (record.clone(), p.clone());
        let ran = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let ran2 = ran.clone();
        super::pre_marker_rename_hook::arm(move || {
            std::fs::rename(&record2, p2.join("record-aside")).unwrap();
            std::fs::write(&record2, b"foreign-record-substitute").unwrap();
            ran2.store(true, std::sync::atomic::Ordering::Relaxed);
        });
        // TWO trash faults: the record-commit withdrawal
        // consumes one, the rollback's target step the
        // other (the displacement confirms, the removal
        // does not).
        super::trash_unlink_fault::arm(2);
        let err = presenter
            .flush_checkpoint()
            .expect_err("the substituted record fails the commit");
        super::pre_marker_rename_hook::disarm();
        super::trash_unlink_fault::reset();
        assert!(
            ran.load(std::sync::atomic::Ordering::Relaxed),
            "the plant hook ran before the freshness check"
        );
        assert!(
            format!("{err:?}").contains("changed after the gate"),
            "the refusal names the freshness loss: {err:?}"
        );
        let pending = presenter
            .pending_recovery
            .as_ref()
            .expect("the rollback stashes its target step");
        assert!(
            pending.displaced_trash.is_some(),
            "the stash carries the confirmed trash"
        );
        assert!(!ckpt.is_file(), "the target stands absent");
        // Restore the entry record; the fault clears.
        std::fs::remove_file(&record).unwrap();
        std::fs::rename(p.join("record-aside"), &record).unwrap();
        presenter
            .flush_checkpoint()
            .expect("the retry resumes and commits");
        assert!(
            presenter.pending_recovery.is_none(),
            "the completed resume clears pending"
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the recovered commit");
        assert_eq!(q.folded_tip(), (Some(0), Some(1)), "the new tip stands");
        assert_eq!(q.fold_totals(), (20, [20, 0, 0, 0]), "the new totals stand");
        assert!(
            !q.recovered_unsettled_prior(),
            "a settled commit reopens directly (no recovery)"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new116_displaced_refuses_foreign_replacement() {
        // P2fix19 NEW-116 (resume refuses foreign): the
        // displaced resume removes ONLY our confirmed
        // trash — a foreign replacement at the displaced
        // name OR at the trash name refuses with pending
        // kept (preserved, never touched); clearing the
        // interference resumes + commits exactly.
        for shape in ["name", "trash"] {
            let (base, out, ckpt, mut presenter) =
                new116_stash_displaced(&format!("displaced-foreign-{shape}"));
            let p = ckpt.parent().unwrap().to_path_buf();
            let trash_name = presenter
                .pending_recovery
                .as_ref()
                .expect("premise: displaced pending")
                .displaced_trash
                .as_ref()
                .expect("premise: trash carried")
                .to_string_lossy()
                .into_owned();
            if shape == "name" {
                std::fs::write(&ckpt, b"foreign-replacement-bytes").unwrap();
            } else {
                let trash = p.join(&trash_name);
                let ours = std::fs::read(&trash).unwrap();
                assert!(!ours.is_empty(), "premise: our trash carries bytes");
                std::fs::rename(&trash, p.join("ours-aside")).unwrap();
                std::fs::write(&trash, b"foreign-trash-bytes").unwrap();
            }
            let err = presenter
                .flush_checkpoint()
                .expect_err("a foreign replacement refuses");
            assert!(
                format!("{err:?}").contains("retries on a later flush"),
                "{shape}: the refusal promises the retry: {err:?}"
            );
            assert!(
                presenter.pending_recovery.is_some(),
                "{shape}: the refused resume keeps pending"
            );
            if shape == "name" {
                assert_eq!(
                    std::fs::read(&ckpt).unwrap(),
                    b"foreign-replacement-bytes",
                    "the foreign replacement survives (never touched)"
                );
                std::fs::remove_file(&ckpt).unwrap();
            } else {
                let trash = p.join(&trash_name);
                assert_eq!(
                    std::fs::read(&trash).unwrap(),
                    b"foreign-trash-bytes",
                    "the foreign trash survives (never touched)"
                );
                std::fs::remove_file(&trash).unwrap();
                std::fs::rename(p.join("ours-aside"), &trash).unwrap();
            }
            presenter
                .flush_checkpoint()
                .expect("the cleared resume commits");
            drop(presenter);
            let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
                .expect("reopen on the recovered commit");
            assert_eq!(q.folded_tip(), (Some(0), Some(0)), "the tip stands");
            assert!(
                !q.recovered_unsettled_prior(),
                "a settled commit reopens directly (no recovery)"
            );
            let _ = std::fs::remove_dir_all(&base);
        }
    }

    #[test]
    fn new115_multilink_trash_removal_confirms_count() {
        // P2fix19 NEW-115 (Tier-1 adjacent edge — the
        // link-count confirm on the NORMAL path): owned
        // removal of a hard-linked entry (nlink 2)
        // removes exactly our name (2→1, count-verified)
        // — the second link survives byte-identical, no
        // trash lingers, and the re-removal of the second
        // link (1→0) confirms too.
        let base = unique_dir("trash-multilink-115");
        let d = base.join("d");
        std::fs::create_dir_all(&d).unwrap();
        let victim = d.join("victim");
        let ours = b"our-multilink-bytes".to_vec();
        std::fs::write(&victim, &ours).unwrap();
        std::fs::hard_link(&victim, d.join("victim2")).unwrap();
        let dir_fd = std::fs::File::open(&d).unwrap();
        let ours_id = super::file_id(&std::fs::File::open(&victim).unwrap()).unwrap();
        let out = super::unlink_owned(&dir_fd, &std::ffi::CString::new("victim").unwrap(), ours_id);
        assert!(matches!(out, Ok(true)), "the first link removes: {out:?}");
        assert_eq!(
            std::fs::read(d.join("victim2")).unwrap(),
            ours,
            "the second link survives byte-identical"
        );
        let out2 = super::unlink_owned(
            &dir_fd,
            &std::ffi::CString::new("victim2").unwrap(),
            ours_id,
        );
        assert!(
            matches!(out2, Ok(true)),
            "the second link removes: {out2:?}"
        );
        assert!(
            std::fs::read_dir(&d)
                .unwrap()
                .flatten()
                .all(|e| { !e.file_name().to_string_lossy().contains(".staging-trash-") }),
            "no trash lingers"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new116_present_displaced_stage_resumes() {
        // P2fix19 NEW-116 (Tier-1 adjacent edge — the
        // EXCHANGE-originated displacement): the
        // rollback's swapped-back stage removal displaces
        // but its trash unlink faults — the rebuilt stash
        // carries the confirmed trash, and the same
        // collector resumes (the stage name must still be
        // absent) + commits + reopens exactly after fault
        // clearance.
        let base = unique_dir("displaced-present-116");
        let out = base.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
        std::fs::write(
            out.join("window-0000000000.json"),
            serde_json::to_string(&super::test_envelope(0, 0, run.clone(), 10)).unwrap(),
        )
        .unwrap();
        let p = base.join("p");
        std::fs::create_dir_all(&p).unwrap();
        let ckpt = p.join("ckpt.json");
        let mut presenter =
            Presenter::open_with_checkpoint(&out, &ckpt, 1, "export").expect("open succeeds");
        presenter.build_service().expect("first fold commits");
        let prior_bytes = std::fs::read(&ckpt).unwrap();
        std::fs::write(
            out.join("window-0000000001.json"),
            serde_json::to_string(&super::test_envelope(1, 0, run, 10)).unwrap(),
        )
        .unwrap();
        presenter
            .build_service_staged()
            .expect("staged fold advances");
        // A substitute at the record name fails the
        // record commit BEFORE its decision (the data
        // publish already ran EXCHANGE — the rollback
        // swaps back, then its stage removal displaces).
        let record = record_path_for(&ckpt);
        let (record2, p2) = (record.clone(), p.clone());
        super::pre_marker_rename_hook::arm(move || {
            std::fs::rename(&record2, p2.join("record-aside")).unwrap();
            std::fs::write(&record2, b"foreign-record-substitute").unwrap();
        });
        super::trash_unlink_fault::arm(2);
        presenter
            .flush_checkpoint()
            .expect_err("the substituted record fails the commit");
        super::pre_marker_rename_hook::disarm();
        super::trash_unlink_fault::reset();
        // The swapback restored the prior; the stage
        // stands displaced (name absent, ours at trash).
        assert_eq!(
            std::fs::read(&ckpt).unwrap(),
            prior_bytes,
            "the target carries the swapped-back prior"
        );
        let pending = presenter
            .pending_recovery
            .as_ref()
            .expect("the rollback rebuilds a resumable stash");
        assert!(
            pending.displaced_trash.is_some(),
            "the stash carries the confirmed trash"
        );
        assert!(
            matches!(pending.arm, super::PublishArm::Present(_)),
            "the stash keeps the EXCHANGE arm"
        );
        // Restore the record; the fault clears.
        std::fs::remove_file(&record).unwrap();
        std::fs::rename(p.join("record-aside"), &record).unwrap();
        presenter
            .flush_checkpoint()
            .expect("the retry resumes and commits");
        assert!(
            presenter.pending_recovery.is_none(),
            "the completed resume clears pending"
        );
        drop(presenter);
        let q = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
            .expect("reopen on the recovered commit");
        assert_eq!(q.folded_tip(), (Some(0), Some(1)), "the new tip stands");
        assert_eq!(q.fold_totals(), (20, [20, 0, 0, 0]), "the new totals stand");
        assert!(
            !q.recovered_unsettled_prior(),
            "a settled commit reopens directly (no recovery)"
        );
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn new118_first_contact_new_namespace_refuses() {
        // P2fix19 NEW-118 (first-contact authority): a
        // valid-but-conflicting record that APPEARED after
        // a markerless open (fresh or discarded start)
        // refuses BEFORE either decision — never adopted
        // as the write baseline. The target, the marker,
        // and any recoverable payload survive. Pre-fix:
        // the write adopts the stranger and commits (RED).
        for load in ["fresh", "discarded"] {
            let base = unique_dir(&format!("first-contact-newns-{load}"));
            let out = base.join("out");
            std::fs::create_dir_all(&out).unwrap();
            let run = serde_json::json!({"pid": 1, "starttime": 2, "boot_id": "12345678-9abc-def0-1234-56789abcdef0"});
            std::fs::write(
                out.join("window-0000000000.json"),
                serde_json::to_string(&super::test_envelope(0, 0, run, 10)).unwrap(),
            )
            .unwrap();
            let p = base.join("p");
            std::fs::create_dir_all(&p).unwrap();
            let ckpt = p.join("ckpt.json");
            if load == "discarded" {
                std::fs::write(&ckpt, b"torn-non-json-{{{").unwrap();
            }
            let mut presenter = Presenter::open_with_checkpoint(&out, &ckpt, 1, "export")
                .expect("markerless open succeeds");
            // A valid record for ANOTHER transaction
            // appears after open (first contact).
            let stranger = super::render_settlement_record(&super::SettledRecord {
                target_sha256: "ab".repeat(32),
                checkpoint_seq: 7,
            });
            let record_path = record_path_for(&ckpt);
            std::fs::create_dir_all(record_path.parent().unwrap()).unwrap();
            std::fs::write(&record_path, &stranger).unwrap();
            presenter
                .build_service_staged()
                .expect("staged fold advances");
            super::marker_probe::take();
            let err = presenter
                .flush_checkpoint()
                .expect_err("first contact with a conflicting record refuses");
            assert!(
                format!("{err:?}").contains("first contact"),
                "{load}: the refusal names first contact: {err:?}"
            );
            assert_eq!(
                super::marker_probe::take(),
                0,
                "{load}: neither decision ran"
            );
            assert_eq!(
                std::fs::read(&record_path).unwrap(),
                stranger,
                "{load}: the marker survives byte-identical"
            );
            if load == "fresh" {
                assert!(!ckpt.is_file(), "the target stands absent (no write)");
            } else {
                assert_eq!(
                    std::fs::read(&ckpt).unwrap(),
                    b"torn-non-json-{{{",
                    "the recoverable payload survives (never replaced)"
                );
            }
            let marker_dir = record_path.parent().unwrap().to_path_buf();
            for dir in [&p, &marker_dir] {
                assert!(
                    std::fs::read_dir(dir)
                        .unwrap()
                        .flatten()
                        .all(|e| !e.file_name().to_string_lossy().contains(".staging-")),
                    "{load}: zero staging (refused before either decision)"
                );
            }
            let _ = std::fs::remove_dir_all(&base);
        }
    }

